import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"2022年 · 秘诀在少数赢家","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2022年.md","filePath":"05_quotes/by-year/2022年.md"}'),r={name:"05_quotes/by-year/2022年.md"};function u(c,e,q,s,h,b){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2022年-·-秘诀在少数赢家" tabindex="-1">2022年 · 秘诀在少数赢家 <a class="header-anchor" href="#_2022年-·-秘诀在少数赢家" aria-label="Permalink to &quot;2022年 · 秘诀在少数赢家&quot;">​</a></h1><blockquote><p>随着鲜花的绽放，杂草的重要性就会消退。长期来看，只需要少数几个赢家就能创造奇迹。——巴菲特（92岁）</p></blockquote><p>本页收录2022年致股东信中的经典语录。本年巴菲特坦诚回顾58年投资生涯，揭示&quot;约12个好决定&quot;创造奇迹的秘密，并收录查理·芒格的精辟语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>查理和我不是选股者，而是选企业者。</p></blockquote><blockquote><p>股票经常以真正愚蠢的价格交易，无论高低。&quot;有效&quot;市场只存在于教科书中。</p></blockquote><blockquote><p>随着鲜花的绽放，杂草的重要性就会消退。长期来看，只需要少数几个赢家就能创造奇迹。是的，及早开始并长寿也有帮助。</p></blockquote><blockquote><p>当有人告诉你所有回购都损害股东或国家，或特别有利于首席执行官时，你听到的不是经济学文盲就是巧舌如簧的煽动家（这两种身份并不互相排斥）。</p></blockquote><blockquote><p>资本主义有两面性：这个系统一方面产生越来越多的失败者，另一方面却源源不断地提供更好的产品和服务。</p></blockquote><blockquote><p>我已经投资了80年——超过我们国家寿命的三分之一。尽管我们的公民热衷于自我批评和自我怀疑，但我从未见过做空美国长期来看是明智的时刻。</p></blockquote><blockquote><p>在伯克希尔，没有终点线。</p></blockquote><blockquote><p>一连串精彩的数字乘以零总是等于零。不要指望发两次财。</p></blockquote><hr><h2 id="查理·芒格语录" tabindex="-1">查理·芒格语录 <a class="header-anchor" href="#查理·芒格语录" aria-label="Permalink to &quot;查理·芒格语录&quot;">​</a></h2><blockquote><p>世界上充满了愚蠢的赌徒，他们的表现不会像耐心的投资者那样好。</p></blockquote><blockquote><p>我只想知道我会死在哪里，这样我就永远不会去那里。</p></blockquote><blockquote><p>耐心是可以学会的。拥有长期的专注力和能够长时间集中注意力于一件事是一个巨大的优势。</p></blockquote><blockquote><p>投资中没有100%确定的事情。因此，使用杠杆是危险的。一连串精彩的数字乘以零总是等于零。</p></blockquote><blockquote><p>沃伦，多想想。你很聪明，而我是对的。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2022年是市场动荡的一年，标普500下跌18.1%，伯克希尔却实现了4%的正收益。巴菲特坦诚回顾58年管理生涯，承认&quot;大多数资本配置决策表现平平&quot;，成功源于&quot;大约十几个真正好的决定——大约每五年一个&quot;。本年还收购了Alleghany保险，浮存金增至1640亿美元。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2022年-翻译-·-01-letters-2022年-核心总结-·-01-letters-2022年-思维导图" tabindex="-1"><a href="/01_letters/2022年/翻译.html">01_letters/2022年/翻译</a> · <a href="/01_letters/2022年/核心总结.html">01_letters/2022年/核心总结</a> · <a href="/01_letters/2022年/思维导图.html">01_letters/2022年/思维导图</a> <a class="header-anchor" href="#_01-letters-2022年-翻译-·-01-letters-2022年-核心总结-·-01-letters-2022年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2022年/翻译]] · [[→ 核心总结|01_letters/2022年/核心总结]] · [[→ 思维导图|01_letters/2022年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2022年/翻译.html">/01_letters/2022年/翻译</a></li></ul>',28)])])}const _=t(r,[["render",u]]);export{i as __pageData,_ as default};
